import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Category {
  PROTEIN = 'Proteins',
  VITAMINS = 'Vitamins',
  SUPPLEMENTS = 'Supplements',
  GEAR = 'Athletic Gear'
}

export interface Product {
  id: string;
  name: string;
  price: number;
  description: string;
  category: Category;
  image: string;
  rating: number;
}

export interface CartItem extends Product {
  quantity: number;
}

export interface HealthTip {
  title: string;
  content: string;
  tags: string[];
}

import { GoogleGenAI, Type } from "@google/genai";

const getAI = () => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing");
  }
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const generateHealthTip = async (topic: string) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Give me a concise bodybuilding or fitness health tip regarding: ${topic}. Include a title, content, and 3 relevant tags.`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          content: { type: Type.STRING },
          tags: { 
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["title", "content", "tags"]
      }
    }
  });

  return JSON.parse(response.text);
};

export const getSmartRecommendation = async (userGoal: string) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `A user says: "${userGoal}". Suggest 2-3 bodybuilding supplements they might need based on this goal. Explain why briefly. Keep it professional and encouraging.`,
  });

  return response.text;
};

